@staticmethod
def invoke(data: Dict[str, Any], endpoints: List[str], override_defaults: bool = False) -> str:
    """
    Open blinds/shades to comfort-optimized positions based on time of day and light conditions.

    Args:
        data: The data dictionary containing devices
        endpoints: List of device endpoint IDs to open
