                if d["endpoint"] == endpoint and (home_id is None or d["home_id"] == home_id):
                    if "state" not in data["devices"][i]:
                        data["devices"][i]["state"] = {}
                    data["devices"][i]["state"]["position"] = position
                    data["devices"][i]["state"]["comfort_optimized"] = True
                    success = True
                    break
            else:
                success = False

            if success:
                results.append({
                    "endpoint": endpoint,
                    "name": device["name"],
                    "success": True,
                    "message": f"Opened {device['name']} to comfort position {position}%",
                    "position": position,
                    "comfort_optimized": True
                })
            else:
                results.append({
                    "endpoint": endpoint,
                    "success": False,
                    "message": f"Failed to update state for device with endpoint {endpoint}"
                })
        else:
            results.append({
